1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE invoice_payments RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        } finally {
50	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	        }
52	    }
53	
54	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
55	    @PostMapping("/seed")
56	    @SuppressWarnings("unchecked")
57	    public void seed(@RequestBody Map<String, Object> fixture) {
58	        List<Map<String, Object>> clients =
59	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
60	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
61	        for (Map<String, Object> c : clients) {
62	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
63	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
64	        }
65	        List<Map<String, Object>> projects =
66	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
67	        for (Map<String, Object> p : projects) {
68	            // status is optional in the fixture — a spec that only cares a project exists leaves it
69	            // out, defaulting to ACTIVE (the same state a fresh project gets, V22__project_status.sql).
70	            Object status = p.getOrDefault("status", "ACTIVE");
71	            // archived is optional too — a spec that only cares a project exists leaves it out,
72	            // defaulting to not-archived (the same state a fresh project gets, V16__project_archived.sql).
73	            boolean archived = Boolean.TRUE.equals(p.getOrDefault("archived", Boolean.FALSE));
74	            jdbc.update(
75	                    "INSERT INTO projects (id, name, client_id, status, archived) VALUES (?, ?, ?, ?, ?)",
76	                    ((Number) p.get("id")).longValue(), p.get("name"),
77	                    ((Number) p.get("clientId")).longValue(), status.toString(), archived);
78	        }
79	        List<Map<String, Object>> contacts =
80	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
81	        for (Map<String, Object> c : contacts) {
82	            jdbc.update(
83	                    "INSERT INTO contacts (id, name, email, contact_role, client_id)"
84	                            + " VALUES (?, ?, ?, ?, ?)",
85	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
86	                    c.get("role"), ((Number) c.get("clientId")).longValue());
87	        }
88	        List<Map<String, Object>> invoices =
89	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
90	        for (Map<String, Object> inv : invoices) {
91	            Object status = inv.getOrDefault("status", "DRAFT");
92	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
93	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
94	            java.time.LocalDate issued = inv.get("issuedDate") != null
95	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
96	                    : java.time.LocalDate.now();
97	            java.time.LocalDate due = inv.get("dueDate") != null
98	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
99	                    : issued.plusDays(30);
100	            // An invoice is built from line items; its amount is the sum of each line's qty times
101	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
102	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
103	            // that still supplies an explicit amount (and no lines) is honoured as-is.
104	            List<Map<String, Object>> lineItems =
